/**
 * bug-report.js — public bug report modal
 *
 * Injects a "Report a bug" floating button + modal on every violawake.com
 * page — the static marketing pages (generated by
 * scripts/generate-marketing.mjs) and the React console app shell alike,
 * since both load this same file as a plain <script> tag. Submits to
 * POST /api/public/bug-report (no auth required). Self-contained; no
 * external dependencies, no build step.
 */
(function () {
  'use strict';

  var API_BASE = 'https://api.violawake.com';
  var ROUTE = '/api/public/bug-report';
  var FALLBACK_EMAIL = 'hello@violawake.com';

  /* ── Styles (uses this site's existing CSS variables — see
     src/styles/global.css :root) ─────────────────────────────────────── */
  var css = [
    '.vbr-fab{',
      'position:fixed;bottom:max(24px,env(safe-area-inset-bottom));right:max(24px,env(safe-area-inset-right));z-index:9000;',
      'background:var(--accent);color:#fff;',
      'border:none;border-radius:999px;padding:10px 18px;',
      'font-size:0.82rem;font-weight:600;font-family:inherit;',
      'cursor:pointer;box-shadow:var(--shadow, 0 4px 20px rgba(0,0,0,0.3));',
      'transition:transform 0.15s,box-shadow 0.15s;',
      'display:flex;align-items:center;gap:6px;min-height:44px;',
    '}',
    '.vbr-fab:hover{transform:translateY(-2px);background:var(--accent-hover);}',
    '.vbr-fab:focus-visible{outline:2px solid var(--accent);outline-offset:3px;}',
    '.vbr-overlay{',
      'display:none;position:fixed;inset:0;z-index:9001;',
      'background:rgba(0,0,0,0.65);backdrop-filter:blur(4px);',
      'align-items:center;justify-content:center;padding:16px;',
    '}',
    '.vbr-overlay.open{display:flex;}',
    '.vbr-dialog{',
      'background:var(--bg-card, #1e2a4a);border:1px solid var(--border);',
      'border-radius:var(--radius);padding:32px;width:100%;max-width:440px;',
      'box-shadow:0 24px 64px rgba(0,0,0,0.5);',
      'font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;',
    '}',
    '.vbr-title{font-size:1.15rem;font-weight:700;margin:0 0 6px;color:var(--text-primary);}',
    '.vbr-subtitle{font-size:0.875rem;color:var(--text-secondary);margin:0 0 24px;line-height:1.5;}',
    '.vbr-label{display:block;font-size:0.82rem;color:var(--text-secondary);margin-bottom:6px;}',
    '.vbr-textarea{',
      'width:100%;background:rgba(255,255,255,0.05);border:1px solid var(--border);',
      'border-radius:var(--radius);padding:12px 14px;font-size:0.95rem;color:var(--text-primary);',
      'font-family:inherit;outline:none;resize:vertical;min-height:100px;',
      'transition:border-color 0.15s,background 0.15s;box-sizing:border-box;',
    '}',
    '.vbr-textarea::placeholder{color:var(--text-secondary);}',
    '.vbr-textarea:focus{border-color:var(--accent);background:rgba(255,255,255,0.08);}',
    '.vbr-count{font-size:0.75rem;color:var(--text-secondary);text-align:right;margin:4px 0 20px;}',
    '.vbr-actions{display:flex;gap:10px;justify-content:flex-end;}',
    '.vbr-btn{',
      'padding:10px 22px;border-radius:999px;font-size:0.875rem;',
      'font-weight:600;font-family:inherit;cursor:pointer;',
      'border:1px solid var(--border);background:transparent;color:var(--text-primary);',
      'transition:background 0.15s;',
    '}',
    '.vbr-btn:hover{background:rgba(255,255,255,0.06);}',
    '.vbr-btn-primary{background:var(--accent);border-color:transparent;color:#fff;}',
    '.vbr-btn-primary:hover{background:var(--accent-hover);}',
    '.vbr-btn:disabled{opacity:0.55;cursor:not-allowed;}',
    '.vbr-btn:focus-visible{outline:2px solid var(--accent);outline-offset:3px;}',
    '.vbr-status{font-size:0.85rem;text-align:center;margin-top:14px;min-height:1.4em;}',
    '.vbr-honeypot{position:absolute;left:-9999px;width:1px;height:1px;overflow:hidden;}',
    '.vbr-footer-link{cursor:pointer;}',
    '@media (max-width:900px){.vbr-fab{display:none;}}'
  ].join('');

  function injectStyles() {
    var el = document.createElement('style');
    el.textContent = css;
    document.head.appendChild(el);
  }

  /* ── HTML ─────────────────────────────────────────────────────────── */
  function buildUI() {
    var page = (window.location.pathname || '/').replace(/\/index\.html$/, '/');
    var MAX = 2000;

    /* Floating button */
    var fab = document.createElement('button');
    fab.className = 'vbr-fab';
    fab.type = 'button';
    fab.setAttribute('aria-label', 'Report a bug');
    fab.setAttribute('aria-haspopup', 'dialog');
    fab.innerHTML = '<svg width="14" height="14" viewBox="0 0 16 16" fill="none" aria-hidden="true"><path d="M8 1a3 3 0 0 1 3 3v.5h1.5a.5.5 0 0 1 0 1H12v.764a5 5 0 0 1 .94 1.237L14.5 7a.5.5 0 0 1-.5.5h-.5A5 5 0 0 1 9 11.9V14H7v-2.1A5 5 0 0 1 2.5 7.5H2A.5.5 0 0 1 2 7l1.56-.499A5 5 0 0 1 4 5.264V4.5H2.5a.5.5 0 0 1 0-1H4V4a3 3 0 0 1 3-3z" fill="currentColor" opacity=".85"/></svg>Report a bug';

    /* Overlay + dialog */
    var overlay = document.createElement('div');
    overlay.className = 'vbr-overlay';
    overlay.setAttribute('role', 'dialog');
    overlay.setAttribute('aria-modal', 'true');
    overlay.setAttribute('aria-labelledby', 'vbr-title');

    overlay.innerHTML = [
      '<div class="vbr-dialog">',
        '<h2 class="vbr-title" id="vbr-title">Report a bug</h2>',
        '<p class="vbr-subtitle">What happened? A sentence or two is enough. We read every report.</p>',
        '<form id="vbr-form" novalidate>',
          '<div class="vbr-honeypot" aria-hidden="true">',
            '<input type="text" name="website" tabindex="-1" autocomplete="off" id="vbr-honeypot" />',
          '</div>',
          '<label class="vbr-label" for="vbr-message">What went wrong</label>',
          '<textarea class="vbr-textarea" id="vbr-message" name="message" ',
            'placeholder="e.g. The compare page table did not load." ',
            'maxlength="' + MAX + '" required></textarea>',
          '<p class="vbr-count" id="vbr-count" aria-live="polite">0 / ' + MAX + '</p>',
          '<input type="hidden" id="vbr-page" name="page" value="' + page + '" />',
          '<div class="vbr-actions">',
            '<button type="button" class="vbr-btn" id="vbr-cancel">Cancel</button>',
            '<button type="submit" class="vbr-btn vbr-btn-primary" id="vbr-submit">Send report</button>',
          '</div>',
        '</form>',
        '<p class="vbr-status" id="vbr-status" role="status" aria-live="polite" aria-atomic="true"></p>',
      '</div>'
    ].join('');

    document.body.appendChild(fab);
    document.body.appendChild(overlay);

    /* ── Interactions ─────────────────────────────────────────────── */
    var form      = document.getElementById('vbr-form');
    var textarea  = document.getElementById('vbr-message');
    var countEl   = document.getElementById('vbr-count');
    var statusEl  = document.getElementById('vbr-status');
    var submitBtn = document.getElementById('vbr-submit');
    var cancelBtn = document.getElementById('vbr-cancel');
    var honeypot  = document.getElementById('vbr-honeypot');

    function openModal() {
      overlay.classList.add('open');
      fab.setAttribute('aria-expanded', 'true');
      textarea.focus();
      statusEl.textContent = '';
    }

    function closeModal() {
      overlay.classList.remove('open');
      fab.setAttribute('aria-expanded', 'false');
      fab.focus();
    }

    textarea.addEventListener('input', function () {
      var len = textarea.value.length;
      countEl.textContent = len + ' / ' + MAX;
    });

    fab.addEventListener('click', openModal);
    cancelBtn.addEventListener('click', closeModal);

    overlay.addEventListener('click', function (e) {
      if (e.target === overlay) closeModal();
    });

    document.addEventListener('keydown', function (e) {
      if (e.key === 'Escape' && overlay.classList.contains('open')) closeModal();
    });

    form.addEventListener('submit', function (e) {
      e.preventDefault();
      var msg = textarea.value.trim();
      if (!msg || msg.length < 10) {
        statusEl.style.color = 'var(--error)';
        statusEl.textContent = 'Please describe the bug (at least 10 characters).';
        textarea.focus();
        return;
      }

      submitBtn.disabled = true;
      submitBtn.textContent = 'Sending…';
      statusEl.textContent = '';

      fetch(API_BASE + ROUTE, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          message: msg,
          page: (document.getElementById('vbr-page').value || '').trim(),
          website: honeypot ? honeypot.value : ''
        })
      })
      .then(function (r) {
        if (!r.ok) throw new Error('HTTP ' + r.status);
        return r.json();
      })
      .then(function () {
        // Only shown as success once the backend actually confirmed receipt
        // (a non-2xx or network failure falls through to .catch below) — a
        // visitor never sees "sent" for a report that was silently dropped.
        statusEl.style.color = 'var(--success)';
        statusEl.textContent = 'Got it — thank you. We read every report.';
        submitBtn.textContent = 'Sent';
        form.reset();
        countEl.textContent = '0 / ' + MAX;
        setTimeout(closeModal, 2200);
      })
      .catch(function () {
        statusEl.style.color = 'var(--error)';
        statusEl.textContent = 'Something went wrong. Try emailing ' + FALLBACK_EMAIL + ' instead.';
        submitBtn.disabled = false;
        submitBtn.textContent = 'Send report';
      });
    });
  }

  /* ── Footer link ──────────────────────────────────────────────────── */
  // React app footer (Layout.tsx) uses .app-footer-links; the static
  // marketing shell (generate-marketing.mjs) uses .static-footer-links.
  var FOOTER_LINKS_SELECTOR = '.app-footer-links, .static-footer-links';

  function addFooterLink(links) {
    if (links.querySelector('.vbr-footer-link')) return;
    var a = document.createElement('a');
    a.href = '#';
    a.className = 'vbr-footer-link';
    a.textContent = 'Report a bug';
    a.setAttribute('aria-label', 'Report a bug');
    a.addEventListener('click', function (e) {
      e.preventDefault();
      var overlay = document.querySelector('.vbr-overlay');
      if (overlay) {
        overlay.classList.add('open');
        var textarea = document.getElementById('vbr-message');
        if (textarea) textarea.focus();
      }
    });
    links.appendChild(a);
  }

  function injectFooterLink() {
    // Static marketing pages render the footer into the initial HTML, so it
    // is present immediately. The React console app (app.html / app/*)
    // mounts its footer after this script's DOMContentLoaded handler has
    // already run, so a one-shot querySelector here would silently miss it.
    // Try immediately, then fall back to watching the DOM until it appears.
    var links = document.querySelector(FOOTER_LINKS_SELECTOR);
    if (links) {
      addFooterLink(links);
      return;
    }

    var observer = new MutationObserver(function () {
      var found = document.querySelector(FOOTER_LINKS_SELECTOR);
      if (found) {
        addFooterLink(found);
        observer.disconnect();
      }
    });
    observer.observe(document.body, { childList: true, subtree: true });
  }

  /* ── Bootstrap ────────────────────────────────────────────────────── */
  function init() {
    injectStyles();
    buildUI();
    injectFooterLink();
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
}());
